/* Pure domain functions. No network or authentication service is implied. */
(function(root){
 const iso=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);
 const today=()=>iso(new Date());
 const month=()=>today().slice(0,7);
 const id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
 const minutes=t=>{if(!/^\d{2}:\d{2}$/.test(t||''))return NaN;let[h,m]=t.split(':').map(Number);return h<24&&m<60?h*60+m:NaN};
 function duration(start,end,rest=0){let a=minutes(start),b=minutes(end);if(!Number.isFinite(a+b)||!Number.isFinite(+rest)||+rest<0)return 0;let span=b-a;if(span<0)span+=1440;return Math.max(0,span-Number(rest));}
 function workMinutes(r){return r.status==='결근'||!r.in||!r.out?0:duration(r.in,r.out,r.break||0);}
 function payroll(db,employee,period){let rows=db.records.filter(r=>r.employee===employee.id&&r.date.startsWith(period));let mins=rows.reduce((s,r)=>s+workMinutes(r),0);let base=Math.round(mins/60*Number(employee.wage));let extra=db.payroll[employee.id+'_'+period]||{};let weekly=Number(extra.weekly||0),night=Number(extra.night||0),other=Number(extra.other||0);return {rows,minutes:mins,base,weekly,night,other,total:base+weekly+night+other,confirmed:!!extra.confirmed};}
 function coverage(shift){let assigned=new Set(shift.employees).size;return {assigned,missing:Math.max(0,Number(shift.required)-assigned)};}
 function recordStatus(start,actual){return !actual?'예정':minutes(actual)>minutes(start)?'지각':'정상';}
 function csvCell(value){let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
 function seed(){const day=today(),m=month(),date=n=>m+'-'+String(n).padStart(2,'0');const employees=['김민수','이지은','박현우','최유진','정민호','한지수'].map((name,i)=>({id:'e'+(i+1),name,phone:'010-1234-'+String(5601+i),email:'staff'+(i+1)+'@example.com',position:i===0?'매니저':'스태프',type:i<3?'주중':'주말',status:'재직',join:m+'-01',wage:12000,login:'staff'+(i+1),conditions:{probation:'없음',break:60,weekly:'조건 확인',night:'조건 확인',start:m+'-01',end:m+'-28'},fixed:[{day:1,start:'09:00',end:'18:00',break:60},{day:3,start:'09:00',end:'18:00',break:60},{day:5,start:'09:00',end:'18:00',break:60}],insurance:['국민연금','건강보험','고용보험','산재보험'].map(name=>({name,joined:false,date:''})),leaveGranted:5,contracts:[]}));
 const shifts=[];let days=new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate();for(let n=1;n<=days;n++){let d=date(n),w=new Date(d+'T12:00:00').getDay();if(w===0)continue;shifts.push({id:'s'+n,date:d,start:'09:00',end:'18:00',break:60,required:w===6?6:4,employees:w===6?['e1','e2','e3','e4','e5']:['e1','e2','e3','e4'],note:'팝업 운영'});}
 if(!shifts.some(s=>s.date===day))shifts.push({id:'stoday',date:day,start:'09:00',end:'18:00',break:60,required:4,employees:['e1','e2','e3','e4'],note:'오늘 운영'});
 let records=[];for(let s of shifts.filter(s=>s.date<day)){for(let [i,e]of s.employees.entries()){let absent=Number(s.date.slice(-2))%11===0&&i===2,late=Number(s.date.slice(-2))%5===0&&i===0;records.push({id:id(),shiftId:s.id,employee:e,date:s.date,start:s.start,end:s.end,in:absent?'':late?'09:10':'09:00',out:absent?'':'18:00',break:60,status:absent?'결근':late?'지각':'정상',method:i%2?'QR':'OTP',location:'성수 보람 팝업',note:'',history:[]});}}
 return {version:1,employees,shifts,records,requests:[],leaves:[],payroll:{},notifications:[{id:id(),type:'인원 부족',title:'다가오는 주말 근무 인원을 확인해 주세요',body:'근무 일정에서 필요 인원과 배정 인원을 비교하고 추가 배정할 수 있어요.',date:day,read:false,target:'schedule',employee:null},{id:id(),type:'시스템',title:'Boram에 오신 것을 환영해요',body:'이 서비스는 브라우저에 데이터를 저장하는 체험 버전입니다. 관리자와 직원 화면을 전환해 전체 흐름을 확인하세요.',date:day,read:false,target:'home',employee:null}],store:{name:'성수 보람 팝업',code:'BRM2026',owner:'김보람',business:'123-45-67890',address:'서울 성동구 연무장길 12',phone:'02-123-4567',email:'boram@example.com',start:m+'-01',end:m+'-'+days,open:'09:00',close:'22:00',holidays:'일요일',policy:'실제 출퇴근시간에서 휴게시간을 제외',branches:'성수 보람 팝업',methods:['OTP','QR'],networks:'192.168.0.0/24',radius:100,otpSeconds:300},audit:[]};}
 root.Boram={iso,today,month,id,minutes,duration,workMinutes,payroll,coverage,recordStatus,csvCell,seed};
})(typeof window!=='undefined'?window:globalThis);
